@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_text_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_text_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_text_before_898_writes_no_enumerator_names():
    assert bytes(
        v859.TextPacket(
            body=v859.TextPacket.MessageOnly(type=v859.TextPacketType.RAW, message="hi"), xuid="x", platform_id="p"
        )
    ) == bytes(
        v924.TextPacket(
            body=v924.TextPacket.MessageOnly(type=v924.TextPacketType.RAW, message="hi"), xuid="x", platform_id="p"
        )
    )
